TLM.f("Tempora/Quad4-4",{"officium":"Feria Quinta infra Hebdomadam IV in Quadragesima","rule":["no Gloria","Suffragium=Sanctorum;Vivis;;","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"fallback":"Tempora/Quad4-0","sections":{"Introitus":[{"k":"ref","la":"Ps 104:3-4"},{"k":"text","la":"Lætétur cor quæréntium Dóminum: quǽrite Dóminum, et confirmámini: quǽrite fáciem ejus semper."},{"k":"ref","la":"Ps 104:1"},{"k":"text","la":"Confitémini Dómino, et invocáte nomen ejus: annuntiáte inter gentes ópera ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Lætétur cor quæréntium Dóminum: quǽrite Dóminum, et confirmámini: quǽrite fáciem ejus semper."}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, quos jejúnia votíva castígant, ipsa quoque devótio sancta lætíficet; ut, terrénis afféctibus mitigátis, facílius cœléstia capiámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Regum"},{"k":"ref","la":"4 Reg 4:25-38"},{"k":"text","la":"In diébus illis: Venit múlier Sunamítis ad Eliséum in montem Carméli: cumque vidísset eam vir Dei e contra, ait ad Giézi púerum suum: Ecce Sunamítis illa. Vade ergo in occúrsum ejus, et dic ei: Recte ne ágitur circa te, et circa virum tuum, et circa fílium tuum? Quæ respóndit: Recte. Cumque venísset ad virum Dei in montem, apprehéndit pedes ejus: et accéssit Giézi, ut amovéret eam. Et ait homo Dei: Dimítte illam: ánima enim ejus in amaritúdine est, et Dóminus celávit a me, et non indicávit mihi. Quæ dixit illi: Numquid petívi fílium a dómino meo? Numquid non dixi tibi: Ne illúdas me? Et ille ait ad Giézi: Accínge lumbos tuos, et tolle báculum meum in manu tua, et vade. Si occurrérit tibi homo, non salútes eum: et si salutáverit te quíspiam, non respóndeas illi: et pones báculum meum super fáciem púeri. Porro mater púeri ait: Vivit Dóminus et vivit ánima tua, non dimíttam te. Surréxit ergo, et secútus est eam. Giézi autem præcésserat ante eos, et posúerat báculum super fáciem púeri, et non erat vox neque sensus: reversúsque est in occúrsum ejus, et nuntiávit ei, dicens: Non surréxit puer. Ingréssus est ergo Eliséus domum, et ecce, puer mórtuus jacébat in léctulo ejus: ingressúsque clausit óstium super se et super púerum: et orávit ad Dóminum. Et ascéndit, et incúbuit super púerum: posuítque os suum super os ejus, et óculos suos super óculos ejus, et manus suas super manus ejus: et incurvávit se super eum: et calefácta est caro púeri. At ille revérsus, deambulávit in domo, semel huc atque illuc: et ascéndit et incúbuit super eum: et oscitávit puer sépties, aperuítque oculos. At ille vocávit Giézi, et dixit ei: Voca Sunamítidem hanc. Quæ vocáta ingréssa est ad eum. Qui ait: Tolle fílium tuum. Venit illa, et córruit ad pedes ejus, et adorávit super terram: tulítque fílium suum, et egréssa est, et Eliséus revérsus est in Gálgala."}],"Graduale":[{"k":"ref","la":"Ps 73:20, 19, 22"},{"k":"text","la":"Réspice, Dómine, in testaméntum tuum: et ánimas páuperum tuórum ne obliviscáris in finem."},{"k":"text","la":"Exsúrge, Dómine, júdica causam tuam: memor esto oppróbrii servórum tuórum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 7:11-16"},{"k":"text","la":"In illo témpore: Ibat Jesus in civitátem, quæ vocátur Naim: et ibant cum eo discípuli ejus et turba copiósa. Cum autem appropinquáret portæ civitátis, ecce, defúnctus efferebátur fílius únicus matris suæ: et hæc vídua erat, et turba civitátis multa cum illa. Quam cum vidísset Dóminus, misericórdia motus super eam, dixit illi: Noli flere. Et accéssit et tétigit lóculum. - Hi autem, qui portábant, stetérunt - Et ait: Adoléscens, tibi dico, surge. Et resédit, qui erat mórtuus, et cœpit loqui. Et dedit illum matri suæ. Accépit autem omnes timor: et magnificábant Deum, dicéntes: Quia Prophéta magnus surréxit in nobis: et quia Deus visitávit plebem suam."}],"Offertorium":[{"k":"ref","la":"Ps 69:2, 3, 4"},{"k":"text","la":"Dómine, ad adjuvándum me festína: confundántur omnes, qui cógitant servis tuis mala."}],"Secreta":[{"k":"text","la":"Purífica nos, miséricors Deus: ut Ecclésiæ tuæ preces, quæ tibi gratæ sunt, pia múnera deferéntes, fiant expiátis méntibus gratióres."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 70:16-17, 18"},{"k":"text","la":"Dómine, memorábor justítiæ tuæ solíus: Deus, docuísti me a juventúte mea: et usque in senéctam et sénium, Deus, ne derelínquas me."}],"Postcommunio":[{"k":"text","la":"Cœléstia dona capiéntibus, quǽsumus, Dómine: non ad judícium proveníre patiáris, quæ fidélibus tuis ad remédium providísti."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Pópuli tui, Deus, institútor et rector, peccáta, quibus impugnátur, expélle: ut semper tibi plácitus, et tuo munímine sit secúrus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"d856280c017fb56f":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da nas koje obuzdavaju posvećeni postovi obraduje sveta pobožnost te lakše prihvatimo ono što je nebesko, pošto smo ukrotili zemaljske sklonosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da nas koje trapi svečani post, razveseli sveta pobožnost’ te svladavši svjetske težnje lakše dostignemo nebeske, Po G. n.","knRef":"Kniewald 1942, str. 182–183 (snimka 92) (OCR)"},"7daca6257542ffd7":{"t":"Očisti nas, milosrdni Bože, da ti molitve tvoje Crkve, koje su tebi mile kad su združene s prikazanim svetim darovima, budu još milije, pošto smo očistili duše.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Očisti nas, milosrdni Bože, da Ti budu milije molbe Tvoje Crkve, kojima se prinose sveti darovi, nakon što su nam duše pomirene s Tobom, po G. n.","knRef":"Kniewald 1942, str. 186–187 (snimka 94) (OCR)"},"9395511abb5e6c81":{"t":"<i>Pomolimo se</i>.\nDopusti, molimo, Gospodine, da nebeski darovi koje si dao kao lijek svojim vjernima ne budu na osudu nama koji ih primamo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404e7ca91e475256":{"t":"Ps 104, 3-4, Ps 104, 1\n(Ps 104, 3-4) Neka se veseli srce onih koji traže Gospodina. Tražite Gospodina i budite hrabri, tražite uvijek lice njegovo. (Ps 104, 1) Hvalite Gospodina i zazivajte ime njegovo, navješćujte među narodima djela njegova.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 104, 3-4) Neka se veseli srce onih koji traže Gospodina. Tražite Gospodina i budite hrabri, tražite uvijek lice njegovo.","kn":"(Ps. 104, 3, 4). Neka se raduje srce onih, koji traže Ga=podina; tražite Gospodina i njegovu moć, tražite vazda njegovo lice! (Ps. 104, 1) Slavite Gospodina i zazivajte ime njegovo, navlještajte djela njegova među narodima'. Slava Ocu . . . Neka se . . .","knRef":"Kniewald 1942, str. 184–185 (snimka 93) (OCR)"},"417c9bad1f6e84bd":{"t":"2* Kr 4, 25-38\nČitanje knjige Kraljeva. U one dane dođe k Elizeju na goru Karmel neka Sunamićanka. Kad je Božji čovjek iz daljine ugleda i vidi da ide prema njemu, reče svom slugi Gjeziju: Vidiš li onu Sunamićanku. Pođi joj ususret i pitaj je: Kako si ti, tvoj muž i tvoj sin? Ona odgovori: Dobro. Kada pristupi bliže Božjem čovjeku na gori, obujmi mu noge, a Gjezi je htjede odstraniti. Ali mu Božji čovjek reče: Pusti je, jako je žalosna, a Gospodin je sakrio od mene i nije mi objavio. Ona reče: Ja nisam tražila sina od svojega gospodara, a tebi sam kazala: Nemoj me varati. Elizej reče Gjeziju: Pripaši svoje bokove, uzmi u svoju ruku moj štap i pođi. A koga sretneš, ne pozdravljaj ga. Ako te tko pozdravi, ne odzdravljaj mu. Moj štap metnut ćeš na lice djetetu. Tada djetetova majka reče: Tako da je živ Gospodin i tako da živi tvoja duša, neću te pustiti. Pa ustane i on i išao je za njom. Gjezi je pošao prije njih, stavio štap na lice djeteta, ali se nije čulo ni glasa ni znaka života pa se vrati ususret Elizeju i kaže mu, da dijete nije ustalo. Tada Elizej uđe u kuću. Mrtvo dijete leži u svojoj posteljici. On zatvori vrata za sobom, osta sam sa djetetom i pomoli se Gospodinu. Pristupi, legne povrh djeteta, stavi svoja usta na njegova usta, svoje oči na njegove oči, svoje ruke na njegove ruke i savi se nad njim i stopli tijelo djeteta. Ustane, prošeta se amo tamo jedanput po kući, vrati se, ponovo leže na dijete, koje zijevne sedam puta i otvori oči. Pozva Gjezija i reče mu: Zovi tu Sunamićanku! I ona na poziv dođe k njemu. On joj reče: Uzmi svoga sina! Ona padne k njegovim nogama, pokloni se do zemlje, uzme svoga sina i izađe, a Elizej se vrati u Galgalu. [* Vulgata Sixto-Clementina sadrži četiri knjige o kraljevima, od kojih se prve dvije u drugim novijim izdanjima označavaju kao knjige o Samuelu: I Reg, II Reg, III Reg, IV Reg odgovaraju 1 Sam, 2 Sam, 1 Kr, 2 Kr]","kn":"Citaij'e knjige Kraljeva (4. Kralj. 4, 25-38). U one Gane. Žena Sunamićanka dođe k Elizeju na Soru Kaimelsku; a kad je čovjek Božji ugleda, prema sebi, reče Gleziju, momku svojemu; Evo one Su~ namićanke. Iziđi joj dakle ususret, i reci joj; Kako si ti, i muž tvoj, i sin tvoj? A ona odgovori; Dobro. A kad dođe čovjeku Božjemu na goru, obujmi noge njegove, a Giezi pristupi, da je odstrani. Ali čovjek Božji reče; Pusti je, jer joj je duša u tuzi, a Gospodin sakri od mene, i ne objavi mi. A ona reče; Nijesam li iskala sina od gosip.odara svoga? Nijesam l'i ti kazala; nemoj me varati?^ A on reče Gieziju; Pripaši bokove svoje, i uzmi štap u ruku svoju, i pođi. Ako kogagod sretneš, .ne {pozdravljaj ga; i ako* te ko pozdravi, ne ozdravljaj mu; i stavit ćeš štap moj na lice djeteta. Tada reče mati djeteta; Tako da je ziv Gospodin, i tako da živi duša moja, ne ću te pustiti. Ustade dakle, i iđaše za njom. A ljiezi bješe otišao pred njima i stavi štap nai lice djetetu, 1 ne bje glasa ni osjećanja; i povrati se ususret njemu, i javi mu govoreći; Dijete nije ustalo. Uđe dakle Elizej u kuću i gle! dijete mrtvo leži na posteljici svojoj; i ušavši zatvori vrata za sobom, i pomoli se Gospodinu. Po tom pristujpi, i leže povrh djeteta; i stavi usta svoja na usta njegova, i oči svoje na oči njegove, i ruke svoje na ruke njegove, i savi se nad njih; i stopli se tijelo djeteta. A on ustade, i proseta se po kući jednom amo i tamo, Pa pristupi i leže povrh njega, i zijevnu dijete se- dam puta i otvori oči. I pozva Giezija i reče m.u; Zovi tu Sunamićanku. I ona; pli'zvana. uđe. ’ : njemu. A on reče; Uzmi sina svojega. I ,^.h|avši’‘&ade k nogama njegovim, i ipoIžaH'i'' uzme sina svojega i iziđe, a M'- ' V: .- Galgalu. - --- - - H-J-","knRef":"Kniewald 1942, str. 186–187 (snimka 94) (OCR)"},"ecf5cc1e67d7ef9f":{"t":"Ps 73, 20 i 19 i 22\nPogledaj, Gospodine, na svoj zavjet i duše siromaha svojih ne zaboravi dokraja. Ustani, Gospodine, brani stvar svoju, spomeni se sramote slugu svojih.","v":"et → ∅","kn":"IPs. 73, 20, 19, 22). Pogledaj, Gospodine, na zavjet svoj, i ne zaboravi do kraja svojih ubogih. Ustani, Gospodine, sudi pravdu svoju, sjeti se sramote slugu svojih!","knRef":"Kniewald 1942, str. 186–187 (snimka 94) (OCR)"},"8383eb8c3946811f":{"t":"Lk 7, 11-16\nSlijedi sveto Evanđelje po Luki. U ono vrijeme išao je Isus u grad Naim. A za njim su išli njegovi učenici i mnogo naroda. Kad se približio vratima grada, gle, iznosili su mrtva jedinca majke udovice, i s njom je iz grada izlazilo mnoštvo svijeta. Kad je Isus vidi, sažali mu se te joj reče: Nemoj plakati! I nosioci stanu, a on pristupi bliže, dotakne se nosila i reče: Mladiću, tebi govorim, ustani! Tada mrtvi mladić sjedne i stade govoriti. I dade ga Isus njegovoj majci. Strah obuze sve prisutne te su slavili Boga govoreći: Velik je prorok ustao među nama, i Bog je pohodio svoj narod!","kn":"t Slijedi sveto evanđelje po Luki (7, 11-16). U ono vrijeme išao je Isus u grad Naim. A išli su s njim njegovi učenici i mnogo naroda. Kad se približio gradskim vratima, iznosili su mrtva jedinca u majke, koja je bila udovica. A izlazilo je s njom iz grada mnogo naroda. Kad ju ugleda Gospodin, sažali mu se i reče joj: Ne plači! I pristupi, dotače se nosila, a nosioci stadoše. Tada on reče: Mladiću, kažem ti: Ustani! I sjedne onaj, koji je bio mrtav, i poče govoriti, a on ga dade njegovoj majci. I sve obuze strah, i hvalili su Boga govoreći: Ustao je među nama velik prorok i Bog je pohodio svoj narod.","knRef":"Kniewald 1942, str. 566–567 (snimka 284) (OCR)"},"12abd5d5fa656097":{"t":"Ps 69, 2 i 3 i 4\nGospodine, pohiti da mi pomogneš. Neka se smetu i postide svi koji smišljaju zlo slugama tvojim.","kn":"(Ps. 69, 2-4). Bože, u pomoć mi priteci, nek se smetu, koji smišljahu zlo slugama Tvojim.","knRef":"Kniewald 1942, str. 186–187 (snimka 94) (OCR)"},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo 1 spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože. koji tjelesnim postom obuzdavaš opačine, duh dižeš, daješ krepost i nagrade,' po Kristu, Gospodinu našemu; po kojem veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te 1 nebeske Red i čin sv. mise moći i blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"ebaa7bfab4895b3c":{"t":"Ps 70, 16-17 i 18\nGospodine, slavit ću samo tvoju pravdu! Bože, ti si me učio od mladosti moje, pa sve do duboke starosti ne zapusti me, Bože.","kn":"(Ps. 70, 16-13), Gospodine, opominjat ću se samo Tvoje pravednosti: Bože, Ti si me učio od mladosti moje, i sve do kasne starosti: Bože, nemoj me ostaviti!","knRef":"Kniewald 1942, str. 406–407 (snimka 204) (OCR)"},"ac1d78a7c7b7b736":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nBože, učitelju i vođo svoga naroda, odagnaj grijehe, koji na nj napadaju da ti bude uvijek drag i pod tvojom zaštitom siguran.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomolimo se! Prignite ponizno glave svoje pred Bogom! Bože, koji upravljaš i poučavaš narod svoj, odagnaj grijehe, koji ga napadaju, da bude vazda Tebi prijatan i Tvojom, zaštitom bezbjedan, po G. n.","knRef":"Kniewald 1942, str. 188–189 (snimka 95) (OCR)"}}});
